def describe(text):
    """Description for a menu label, from this table or the plot-type help."""
    t = text.strip().rstrip(".").strip()
    if t.startswith("Plot: "): t = t[6:]
    if t in DESCRIPTIONS: return DESCRIPTIONS[t]
    if t.lower() in _LOWER: return _LOWER[t.lower()]
    from .plothelp import HELP
    if t in HELP: return HELP[t][0]
    return ""
